using sv_e64ee87d123a48018f04a9cca11afab6.Client;

namespace sv_e64ee87d123a48018f04a9cca11afab6.Auth;

// Server-side provider: returns a hardcoded authenticated user and persists
// the claims into PersistentComponentState so the WASM runtime can pick them up.
internal sealed class ServerAuthenticationStateProvider : ServerAuthenticationStateProvider<UserInfo>
{
    private static readonly UserInfo _user = new()
    {
        Email = "bob@example.com",
        Roles = ["User", "Editor"]
    };

    protected override Task<UserInfo?> GetUserAsync()
    {
        return Task.FromResult<UserInfo?>(_user);
    }

    protected override Task<AuthenticationState> GetAuthenticationStateFromUserAsync(UserInfo user)
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, user.Email),
            new(ClaimTypes.Email, user.Email),
        };

        foreach (var role in user.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        var identity = new ClaimsIdentity(claims, "HardcodedAuth");
        var principal = new ClaimsPrincipal(identity);
        return Task.FromResult(new AuthenticationState(principal));
    }
}

